window.TSSR_STUDI_2026 = {"updated":"2026-10-30","title":"Synthèses originales de 9 cours Studi actualisés","guides":[{"id":"studi26-glpi-server-01","title":"GLPI 10 — Vérifier Debian 12 avant installation","goal":"Confirmer système, IP, privilèges et versions avant LAMP.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Cette fiche correspond à GLPI 10.x et PHP 8.2 de Debian 12 ; ne pas utiliser la procédure Debian 13/PHP 8.4 sans vérifier la matrice GLPI.","tags":"prerequis installation check debian bookworm glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier le système","command":"cat /etc/os-release","why":"Affiche Debian et sa version ; le guide suppose Debian 12 Bookworm."},{"text":"Contrôler les adresses réseau","command":"ip -br a","why":"Montre rapidement les interfaces actives et les adresses IP."},{"text":"Vérifier le nom du serveur","command":"hostnamectl","why":"Affiche notamment le nom d’hôte et le système."},{"text":"Vérifier les droits sudo","command":"sudo -l","why":"Indique les commandes autorisées avec sudo ; renseigner son propre mot de passe si demandé."}],"links":[["Versions Debian","https://www.debian.org/releases/"],["Documentation GLPI","https://help.glpi-project.org/documentation/fr"]]},{"id":"studi26-glpi-server-02","title":"GLPI 10 — Installer Apache, MariaDB et PHP 8.2","goal":"Installer les composants LAMP requis pour GLPI 10 sous Debian 12.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"L’installation n’a pas été exécutée sur une VM Debian 12 dans ce travail. Vérifier les paquets avec apt-cache policy et la documentation de la version exacte de GLPI.","tags":"LAMP GLPI apache mariadb php8.2 extensions glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 7).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Actualiser la liste des paquets","command":"sudo apt update","why":"Lit l’index des logiciels disponibles dans les dépôts configurés."},{"text":"Installer Apache et MariaDB","command":"sudo apt install apache2 mariadb-server","why":"Installe le serveur web et la base de données."},{"text":"Installer PHP 8.2 et les modules principaux","command":"sudo apt install php8.2 libapache2-mod-php8.2 php8.2-mysql php8.2-xml php8.2-mbstring php8.2-curl php8.2-gd php8.2-intl php8.2-zip php8.2-bz2","why":"Installe PHP côté Apache et les extensions utiles ; contrôler la liste avec la version GLPI retenue."},{"text":"Vérifier Apache et MariaDB","command":"systemctl status apache2 mariadb","why":"Confirme l’état des deux services ; q permet de sortir de l’affichage."},{"text":"Vérifier PHP","command":"php -v","why":"Affiche la version PHP côté terminal ; vérifier aussi PHP utilisé par Apache."}],"links":[["Guide GLPI","https://help.glpi-project.org/documentation/fr"],["Dépôts Debian","https://packages.debian.org/"]]},{"id":"studi26-glpi-server-03","title":"GLPI 10 — Créer la base et le compte SQL dédié","goal":"Préparer une base GLPI sans utiliser le compte MariaDB root dans l’application.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"MariaDB installé ; accès sudo ; changer la valeur <MOT_DE_PASSE_PERSONNALISE> avant exécution.","warning":"Les lignes SQL se tapent dans MariaDB, pas directement dans Bash. La création de compte suppose un environnement de TP vierge et les autorisations appropriées.","tags":"GLPI base mot de passe MariaDB user compte SQL glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 9).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir MariaDB avec les droits administrateur","command":"sudo mariadb","why":"Sous Debian, l’authentification locale root est souvent associée à sudo/socket Unix."},{"text":"Créer une base dédiée","command":"CREATE DATABASE glpidb CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;","why":"Crée la base de données qui contiendra les tickets et les inventaires."},{"text":"Créer un compte applicatif","command":"CREATE USER 'glpiuser'@'localhost' IDENTIFIED BY '<MOT_DE_PASSE_PERSONNALISE>';","why":"Remplacer le texte entre chevrons par un mot de passe fort dans la console, jamais dans le site public."},{"text":"Accorder les droits sur cette base seulement","command":"GRANT ALL PRIVILEGES ON glpidb.* TO 'glpiuser'@'localhost';","why":"Limite la portée des privilèges à la base glpidb."},{"text":"Quitter la console SQL","command":"EXIT;","why":"Ferme la session MariaDB."},{"text":"Tester le compte dédié","command":"mariadb -u glpiuser -p glpidb","why":"Demande le mot de passe et vérifie l’accès à la base prévue."}],"links":[["Documentation GLPI","https://help.glpi-project.org/documentation/fr"]]},{"id":"studi26-glpi-server-04","title":"GLPI 10 — Déployer le site dans Apache avec dossier public","goal":"Faire pointer Apache vers le sous-dossier public de GLPI.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"GLPI 10 téléchargé depuis la publication officielle, serveur Apache fonctionnel, VirtualHost déjà rédigé. La fiche explique le principe ; utiliser la fiche de VirtualHost complète adaptée au nom d’hôte et au port.","warning":"Ne pas copier un VirtualHost de GLPI 10 vers GLPI 11 sans vérifier la documentation de la branche ; le chemin /public dépend de l’arborescence installée.","tags":"GLPI public webroot virtualhost a2enmod apache configtest glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 13).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Récupérer une archive officielle compatible GLPI 10","command":"Ouvrir la page officielle des versions GLPI","why":"Télécharger la branche exacte voulue ; vérifier intégrité et signature si disponibles."},{"text":"Extraire GLPI et positionner l’application","command":"/var/www/glpi","why":"Emplacement d’exemple ; l’arborescence réelle dépend du guide d’installation retenu."},{"text":"Configurer le DocumentRoot Apache","command":"DocumentRoot /var/www/glpi/public","why":"La racine du site est le dossier public, pas la racine contenant les configurations et données."},{"text":"Activer les modules et le site Apache","command":"sudo a2enmod rewrite","why":"Permet les règles de réécriture nécessaires ; activer aussi le site VirtualHost configuré."},{"text":"Vérifier Apache avant rechargement","command":"sudo apache2ctl configtest","why":"Vérifie que la configuration Apache est syntaxiquement valide."},{"text":"Recharger Apache","command":"sudo systemctl reload apache2","why":"Applique les modifications si configtest indique Syntax OK."}],"links":[["Documentation GLPI 10/11","https://help.glpi-project.org/documentation/fr"],["Versions officielles","https://github.com/glpi-project/glpi/releases"]]},{"id":"studi26-glpi-server-05","title":"GLPI 10 — Terminer l’installation Web et supprimer les accès par défaut","goal":"Réaliser l’assistant puis supprimer les risques évidents après la première connexion.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Les noms de menus et le chemin de suppression varient selon la version. Ne pas supprimer un fichier dont le rôle n’a pas été confirmé ; suivre l’alerte de sécurité exacte GLPI.","tags":"installer première connexion glpi utilisateurs par défaut config install glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 18).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir le site GLPI depuis un navigateur","command":"http://<ADRESSE_IP_OU_NOM_GLPI>/","why":"Remplacer le nom/IP ; l’URL doit mener à l’assistant GLPI."},{"text":"Renseigner la base SQL","command":"Base : glpidb ; utilisateur : glpiuser ; mot de passe : <MOT_DE_PASSE_PERSONNALISE>","why":"Utiliser les valeurs préparées dans MariaDB ; ne pas publier le secret."},{"text":"Vérifier l’écran de fin d’installation","command":"Configuration > Général / alertes de sécurité","why":"Contrôler les alertes de configuration affichées par la version installée."},{"text":"Changer ou désactiver les comptes d’exemple","command":"Administration > Utilisateurs","why":"Les identifiants livrés à l’origine doivent être sécurisés avant accès réseau."},{"text":"Retirer la possibilité de relancer l’installateur","command":"Suivre l’alerte de sécurité de la version GLPI","why":"Éliminer le script d’installation indiqué par GLPI, après vérification du chemin et sauvegarde."},{"text":"Vérifier les droits fichiers","command":"ls -ld /var/www/glpi","why":"La propriété et les droits doivent permettre au serveur web de fonctionner sans rendre les données sensibles publiques."}],"links":[["Sécurisation GLPI","https://help.glpi-project.org/documentation/fr"]]},{"id":"studi26-glpi-server-06","title":"GLPI 10 — Diagnostiquer une page blanche ou erreur HTTP","goal":"Retrouver la cause d’un incident après installation GLPI.","domain":"glpi-server","version":"GLPI 10.x · Debian 12 · Apache · MariaDB · PHP 8.2","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne jamais appliquer chmod 777 pour « réparer » GLPI. Diagnostiquer avant de changer les permissions.","tags":"GLPI panne 500 blanche apache php logs erreur glpi-server Installer et sécuriser un serveur GLPI 10 sur Debian 12","source":"Synthèse personnelle du cours Studi « Installer et sécuriser un serveur GLPI 10 sur Debian 12 » (p. 25).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier la disponibilité d’Apache","command":"systemctl status apache2","why":"L’état active/running indique que le service tourne."},{"text":"Tester la syntaxe de la configuration","command":"sudo apache2ctl configtest","why":"Une erreur de syntaxe empêche souvent le rechargement du site."},{"text":"Lire les derniers messages du service","command":"sudo journalctl -u apache2 -n 30 --no-pager","why":"Montre les messages récents liés à Apache."},{"text":"Vérifier la version PHP du terminal","command":"php -v","why":"Confirme la version PHP CLI ; comparer à celle d’Apache."},{"text":"Contrôler la disponibilité SQL","command":"systemctl status mariadb","why":"Une base arrêtée empêche GLPI de charger normalement."},{"text":"Vérifier le journal de l’application","command":"Consulter les journaux GLPI indiqués par la documentation de sa version","why":"Chercher l’erreur exacte avant de modifier la configuration ou les droits."}],"links":[["Documentation GLPI","https://help.glpi-project.org/documentation/fr"]]},{"id":"studi26-glpi-inv-01","title":"GLPI — Ajouter un ordinateur manuellement","goal":"Déclarer un poste dans l’inventaire du parc.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi inventaire ordinateur ajouter matériel manuel glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Choisir la bonne entité GLPI","command":"Sélecteur d’entité en haut de GLPI","why":"L’entité répartit les matériels selon site ou service."},{"text":"Ouvrir le parc des ordinateurs","command":"Actifs > Ordinateurs","why":"Affiche les postes enregistrés."},{"text":"Ajouter un poste","command":"Ajouter","why":"Crée une nouvelle fiche ; renseigner au minimum nom et type."},{"text":"Compléter les caractéristiques","command":"Numéro de série, fabricant, modèle, statut, emplacement","why":"Ces champs permettent de distinguer les postes et de retrouver leur affectation."},{"text":"Enregistrer puis relire la fiche","command":"Ajouter / Enregistrer","why":"Vérifie l’unicité du poste et les données saisies."}],"links":[]},{"id":"studi26-glpi-inv-02","title":"GLPI — Associer écran, imprimante et équipement réseau à un ordinateur","goal":"Relier les actifs entre eux pour refléter le matériel réel.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi écran imprimante switch liaison équipements inventaire glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 8).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Créer l’équipement si absent","command":"Actifs > Moniteurs / Imprimantes / Équipements réseau","why":"Chaque classe d’actifs possède sa propre liste."},{"text":"Ouvrir le matériel concerné","command":"Cliquer sur l’équipement","why":"Affiche les onglets de liaison disponibles."},{"text":"Associer le poste ou l’équipement","command":"Onglet Connexions / Éléments associés","why":"La liaison dépend de la catégorie et des droits du profil."},{"text":"Vérifier depuis la fiche du poste","command":"Actifs > Ordinateurs > poste choisi","why":"Contrôle que les matériels associés apparaissent."}],"links":[]},{"id":"studi26-glpi-inv-03","title":"GLPI — Enregistrer un logiciel, sa version et sa licence","goal":"Retrouver versions, installations et contrats logiciels.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi logiciel version licence inventaire glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir la rubrique logicielle","command":"Actifs > Logiciels","why":"Liste les logiciels connus de GLPI."},{"text":"Créer ou rechercher le logiciel","command":"Ajouter / rechercher","why":"Évite les doublons de noms."},{"text":"Ajouter la version","command":"Versions > Ajouter","why":"Distingue les versions d’un même logiciel."},{"text":"Renseigner la licence si nécessaire","command":"Licences > Ajouter","why":"Documente les droits d’usage sans afficher de clé confidentielle."},{"text":"Vérifier le poste d’installation","command":"Installations / Ordinateurs liés","why":"Confirme la cohérence entre logiciel et poste."}],"links":[]},{"id":"studi26-glpi-inv-04","title":"GLPI 10 — Activer l’inventaire natif","goal":"Préparer GLPI pour recevoir les informations de l’agent.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi inventory agent natif activer règles liaison glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 17).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier la version du serveur GLPI","command":"Configuration > Général > Inventaire","why":"L’emplacement précis dépend des droits et de la branche."},{"text":"Activer l’inventaire natif si disponible","command":"Inventaire : activé","why":"Autorise la réception des informations remontées."},{"text":"Choisir les règles d’import et de liaison","command":"Administration > Règles","why":"Détermine comment un appareil est créé ou associé à une fiche existante."},{"text":"Vérifier une machine test","command":"Actifs > Ordinateurs","why":"Un poste test doit être visible avant de déployer à tout le parc."}],"links":[]},{"id":"studi26-glpi-inv-05","title":"GLPI Agent — Installer et lier un poste Windows ou Linux","goal":"Faire remonter les informations d’un poste vers GLPI 10.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne pas inventer de nom d’installateur ou de version : choisir la version officielle compatible avec le système d’exploitation. Pour GLPI Agent, la version récente peut évoluer.","tags":"GLPI Agent FusionInventory remplacé inventorier windows linux glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 18).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Télécharger GLPI Agent depuis l’éditeur","command":"Page officielle des versions GLPI Agent","why":"Choisir Windows x64 ou un paquet/méthode Linux adapté à la distribution."},{"text":"Installer l’agent sur le poste","command":"Assistant MSI Windows / installation Debian","why":"La procédure dépend du système ; utiliser l’installateur officiel approprié."},{"text":"Renseigner l’URL du serveur GLPI","command":"https://<NOM_SERVEUR_GLPI>/front/inventory.php","why":"L’adresse doit être accessible depuis le poste ; vérifier le point de collecte exact de la version."},{"text":"Exécuter une remontée de test","command":"GLPI Agent > lancer un inventaire / service de l’agent","why":"Déclenche ou attend une tâche d’inventaire sans modifier les matériels."},{"text":"Contrôler l’arrivée du poste","command":"GLPI > Actifs > Ordinateurs","why":"Vérifier l’entité, les doublons et l’horodatage de l’inventaire."}],"links":[["Versions GLPI Agent","https://github.com/glpi-project/glpi-agent/releases"],["Guide GLPI Agent","https://glpi-agent.readthedocs.io/"]]},{"id":"studi26-glpi-inv-06","title":"GLPI — Corriger les doublons après inventaire","goal":"Retrouver l’origine des postes en double ou mal associés.","domain":"glpi-inv","version":"GLPI 10 · inventaire","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi inventaire doublon agent import règles glpi-inv Constituer l’inventaire matériel et logiciel du parc","source":"Synthèse personnelle du cours Studi « Constituer l’inventaire matériel et logiciel du parc » (p. 19).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Identifier les fiches concernées","command":"Actifs > Ordinateurs > rechercher numéro de série","why":"Utiliser numéro de série et nom pour confirmer qu’il s’agit du même poste."},{"text":"Comparer la provenance des données","command":"Informations d’inventaire / historique","why":"Distinguer saisie manuelle et remontée automatique."},{"text":"Contrôler les règles d’import","command":"Administration > Règles","why":"Une règle de liaison insuffisante peut créer des doublons."},{"text":"Tester sur un seul poste","command":"Relancer l’inventaire du poste test","why":"Vérifier la règle avant un déploiement général."}],"links":[]},{"id":"studi26-glpi-itil-01","title":"GLPI — Créer un ticket d’incident et le qualifier","goal":"Tracer la panne dès la réception d’un appel utilisateur.","domain":"glpi-itil","version":"GLPI 10 · assistance","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi itil incident ticket création qualification glpi-itil Exploiter le cycle de vie ITIL du ticket dans GLPI","source":"Synthèse personnelle du cours Studi « Exploiter le cycle de vie ITIL du ticket dans GLPI » (p. 4).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir un nouveau ticket","command":"Assistance > Tickets > Ajouter","why":"Démarre la saisie de l’incident."},{"text":"Sélectionner le type","command":"Incident","why":"Une panne est différente d’une demande de service."},{"text":"Identifier le demandeur et le matériel","command":"Demandeur / Éléments associés","why":"Relie la personne et la machine au ticket."},{"text":"Décrire symptôme et contexte","command":"Titre clair + description factuelle","why":"Indiquer ce qui ne fonctionne pas, depuis quand et le message d’erreur."},{"text":"Classer et affecter","command":"Catégorie / Urgence / Impact / Technicien","why":"Permet le suivi et le bon traitement."},{"text":"Enregistrer puis contrôler","command":"Ajouter","why":"Le ticket doit apparaître avec un identifiant."}],"links":[]},{"id":"studi26-glpi-itil-02","title":"GLPI — Déterminer impact, urgence et priorité","goal":"Attribuer une priorité cohérente à un ticket.","domain":"glpi-itil","version":"GLPI 10 · assistance","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi priorité impact urgence itil glpi-itil Exploiter le cycle de vie ITIL du ticket dans GLPI","source":"Synthèse personnelle du cours Studi « Exploiter le cycle de vie ITIL du ticket dans GLPI » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Évaluer l’impact","command":"Nombre d’utilisateurs ou service concerné","why":"L’impact mesure l’étendue de la panne."},{"text":"Évaluer l’urgence","command":"Temps acceptable avant intervention","why":"L’urgence exprime le délai nécessaire."},{"text":"Consulter la priorité calculée","command":"Matrice de priorité de GLPI","why":"La priorité résulte de la matrice paramétrée par le centre de services."},{"text":"Vérifier les informations","command":"Confirmer avec le demandeur","why":"Éviter une priorité excessive par défaut."}],"links":[]},{"id":"studi26-glpi-itil-03","title":"GLPI — Passer le ticket de Nouveau à Résolu puis Clos","goal":"Maîtriser l’ordre du cycle de vie d’un ticket.","domain":"glpi-itil","version":"GLPI 10 · assistance","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"GLPI ITIL statut nouveau en cours attente résolu clos fermeture glpi-itil Exploiter le cycle de vie ITIL du ticket dans GLPI","source":"Synthèse personnelle du cours Studi « Exploiter le cycle de vie ITIL du ticket dans GLPI » (p. 10).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Prendre le ticket en charge","command":"Nouveau > En cours","why":"Indique qu’un technicien traite l’incident."},{"text":"Ajouter les actions réalisées","command":"Suivis / Tâches","why":"Conserve la traçabilité des tests et interventions."},{"text":"Mettre en attente seulement si justifié","command":"En attente + motif","why":"La raison et le calendrier peuvent modifier le suivi des délais."},{"text":"Proposer une solution","command":"Solution + statut Résolu","why":"Indiquer la correction exacte, pas seulement « OK »."},{"text":"Confirmer le résultat et clôturer","command":"Validation utilisateur / Clos","why":"L’ordre exact dépend des droits et des règles de clôture du service desk."}],"links":[]},{"id":"studi26-glpi-itil-04","title":"GLPI — Distinguer incident et demande de service","goal":"Identifier le bon type avant de créer le ticket.","domain":"glpi-itil","version":"GLPI 10 · assistance","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi itil incident vs demande de service exemple glpi-itil Exploiter le cycle de vie ITIL du ticket dans GLPI","source":"Synthèse personnelle du cours Studi « Exploiter le cycle de vie ITIL du ticket dans GLPI » (p. 16).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier s’il y a panne","command":"Incident : service interrompu ou dégradé","why":"Exemple : l’imprimante ne fonctionne plus."},{"text":"Vérifier si l’utilisateur demande un service prévu","command":"Demande : nouvel accès ou installation planifiée","why":"Exemple : créer un compte ou demander un logiciel."},{"text":"Choisir le type et la catégorie","command":"Type et catégorie dans GLPI","why":"Évite d’appliquer un mauvais circuit de traitement."},{"text":"Appliquer le bon traitement","command":"Incident : rétablir / Demande : valider et réaliser","why":"Les validations et délais peuvent être différents."}],"links":[]},{"id":"studi26-glpi-itil-05","title":"GLPI — Documenter une résolution pour le jury","goal":"Prouver que la panne a été identifiée, corrigée et contrôlée.","domain":"glpi-itil","version":"GLPI 10 · assistance","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi ticket solution oral exam diagnostic traçabilité glpi-itil Exploiter le cycle de vie ITIL du ticket dans GLPI","source":"Synthèse personnelle du cours Studi « Exploiter le cycle de vie ITIL du ticket dans GLPI » (p. 13).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Noter le symptôme initial","command":"Ticket > Description","why":"Ce que signale l’utilisateur."},{"text":"Noter le diagnostic","command":"Suivi ou tâche : tests et résultats","why":"Les tests justifient la cause retenue."},{"text":"Noter la correction","command":"Solution : action réalisée","why":"Préciser l’élément modifié."},{"text":"Vérifier avec l’utilisateur","command":"Test de bon fonctionnement","why":"Évite de clore un ticket non résolu."},{"text":"Clôturer et archiver","command":"Statut Clos / base de connaissances si pertinent","why":"Facilite la réutilisation par le support."}],"links":[]},{"id":"studi26-glpi-forms-01","title":"GLPI — Créer des catégories de tickets simples","goal":"Ranger correctement les demandes réseau, comptes et imprimantes.","domain":"glpi-forms","version":"GLPI 10 · catégories · Formcreator","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi itil catégories formulaires intitulés arbre parent glpi-forms Adapter les champs et formulaires de ticket au besoin métier","source":"Synthèse personnelle du cours Studi « Adapter les champs et formulaires de ticket au besoin métier » (p. 4).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Lister les motifs réels","command":"Ex. Accès / Impression / Réseau / Messagerie","why":"Catégoriser par motif de support, sans arborescence excessive."},{"text":"Ouvrir les catégories de ticket","command":"Configuration > Intitulés > Catégories ITIL","why":"Localise l’arborescence des catégories."},{"text":"Créer la catégorie","command":"Ajouter ; renseigner nom et catégorie parente","why":"Un nom précis évite les erreurs de classement."},{"text":"Choisir le type applicable","command":"Incident / Demande / les deux, selon le besoin","why":"Empêche les catégories inadaptées d’apparaître."},{"text":"Tester dans un ticket","command":"Assistance > Tickets > Ajouter","why":"Vérifie que la catégorie est visible."}],"links":[]},{"id":"studi26-glpi-forms-02","title":"GLPI 10 — Vérifier le plugin Formcreator","goal":"Savoir si les formulaires supplémentaires sont disponibles dans GLPI 10.","domain":"glpi-forms","version":"GLPI 10 · catégories · Formcreator","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Studi mentionne 2.13.10 ; le projet publie également 2.13.11 pour GLPI 10.0.10+. Formcreator est en fin de vie et GLPI 11 intègre un système de formulaires natif.","tags":"formcreator plugin 2.13.10 2.13.11 compatibilité glpi 10 11 glpi-forms Adapter les champs et formulaires de ticket au besoin métier","source":"Synthèse personnelle du cours Studi « Adapter les champs et formulaires de ticket au besoin métier » (p. 10).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Contrôler la version GLPI","command":"Aide / À propos / version","why":"Vérifier qu’il s’agit de GLPI 10.0.x."},{"text":"Contrôler le plugin","command":"Configuration > Plugins / Marketplace","why":"Détermine si Formcreator est installé et activé."},{"text":"Vérifier la compatibilité","command":"Comparer GLPI avec la version de Formcreator","why":"Les versions publiées ne sont pas interchangeables."},{"text":"Repérer les formulaires","command":"Administration > Formulaires (si présent)","why":"Ce menu dépend de l’installation et du profil."}],"links":[["Versions Formcreator","https://github.com/pluginsGLPI/formcreator/releases"],["Documentation GLPI","https://help.glpi-project.org/documentation/fr"]]},{"id":"studi26-glpi-forms-03","title":"GLPI 10 / Formcreator — Créer un formulaire de demande","goal":"Préparer une saisie guidée pour demande récurrente.","domain":"glpi-forms","version":"GLPI 10 · catégories · Formcreator","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Cette procédure suppose GLPI 10 et le plugin Formcreator installé. Sous GLPI 11, rechercher les formulaires natifs ; les menus diffèrent.","tags":"formulaire formcreator demander accès fichier ticket glpi-forms Adapter les champs et formulaires de ticket au besoin métier","source":"Synthèse personnelle du cours Studi « Adapter les champs et formulaires de ticket au besoin métier » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier que Formcreator est opérationnel","command":"Configuration > Plugins / Administration > Formulaires","why":"Ne pas démarrer si le plugin n’est pas actif."},{"text":"Créer le formulaire","command":"Ajouter un formulaire ; nom = Demande d’accès","why":"Un intitulé court explique le besoin."},{"text":"Ajouter des questions essentielles","command":"Demandeur, ressource demandée, justification","why":"Réduire les champs aux informations nécessaires."},{"text":"Configurer les champs obligatoires","command":"Obligatoire : identité / objet de la demande","why":"Empêche les demandes vides ou incompréhensibles."},{"text":"Définir la cible","command":"Ticket GLPI généré par le formulaire","why":"Associe la saisie à l’équipe qui doit traiter."},{"text":"Tester avec un compte demandeur","command":"Envoyer une demande test","why":"Vérifier que le ticket créé contient les bonnes réponses."}],"links":[]},{"id":"studi26-glpi-forms-04","title":"GLPI — Ajouter des champs utiles sans surcharger le ticket","goal":"Garder un ticket facile à remplir et à qualifier.","domain":"glpi-forms","version":"GLPI 10 · catégories · Formcreator","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi champs formulaire liste obligatoire utilisateur glpi-forms Adapter les champs et formulaires de ticket au besoin métier","source":"Synthèse personnelle du cours Studi « Adapter les champs et formulaires de ticket au besoin métier » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Identifier la question manquante","command":"Ex. : nom du poste, lieu, message d’erreur","why":"Une question doit aider directement au diagnostic."},{"text":"Choisir le bon type de champ","command":"Texte, liste, choix unique, date","why":"Limiter la saisie libre quand une liste claire suffit."},{"text":"Rendre obligatoire seulement l’indispensable","command":"Case Obligatoire","why":"Évite les demandes bloquées inutilement."},{"text":"Tester le formulaire en profil utilisateur","command":"Nouvelle demande test","why":"Confirme lisibilité, droits et création du ticket."}],"links":[]},{"id":"studi26-glpi-stats-01","title":"GLPI — Afficher les statistiques mensuelles des tickets","goal":"Obtenir un bilan de volume, délais et satisfaction.","domain":"glpi-stats","version":"GLPI 10 · statistiques","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi statistiques rapport tickets mensuel service desk glpi-stats Piloter le centre de services avec les rapports GLPI","source":"Synthèse personnelle du cours Studi « Piloter le centre de services avec les rapports GLPI » (p. 4).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir les statistiques","command":"Assistance > Statistiques","why":"Affiche les rapports natifs disponibles."},{"text":"Choisir une vue globale","command":"Ticket - Global","why":"Présente les indicateurs de l’ensemble des tickets."},{"text":"Sélectionner la période","command":"Début et fin du mois","why":"Les dates doivent correspondre à l’exercice demandé."},{"text":"Choisir l’entité","command":"Toutes entités ou un site","why":"Vérifier le périmètre de comparaison."},{"text":"Lire les résultats","command":"Volumes / délais / satisfaction","why":"Ne pas confondre délai calendaire et temps réellement travaillé."}],"links":[]},{"id":"studi26-glpi-stats-02","title":"GLPI — Comprendre temps de prise en charge, résolution et clôture","goal":"Distinguer les indicateurs du support.","domain":"glpi-stats","version":"GLPI 10 · statistiques","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"glpi SLA GTI GTR délai durée réelle statistique glpi-stats Piloter le centre de services avec les rapports GLPI","source":"Synthèse personnelle du cours Studi « Piloter le centre de services avec les rapports GLPI » (p. 5).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Repérer la première action","command":"Prise en charge","why":"Mesure la réactivité initiale du support."},{"text":"Repérer la solution","command":"Résolution","why":"Mesure le temps écoulé jusqu’à résolution."},{"text":"Repérer la fermeture","command":"Clôture","why":"Mesure quand le ticket a été définitivement fermé."},{"text":"Lire la durée réelle","command":"Tâches enregistrées","why":"Représente le temps de travail déclaré, différent du temps d’attente."}],"links":[]},{"id":"studi26-glpi-stats-03","title":"GLPI — Analyser des tickets en retard et les SLA","goal":"Comprendre pourquoi un délai a été dépassé.","domain":"glpi-stats","version":"GLPI 10 · statistiques","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"GLPI SLA délais attente calendrier retard GTR glpi-stats Piloter le centre de services avec les rapports GLPI","source":"Synthèse personnelle du cours Studi « Piloter le centre de services avec les rapports GLPI » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Filtrer les tickets en retard","command":"Assistance > Tickets > filtres de date / échéance","why":"Identifier les tickets hors délai."},{"text":"Examiner le calendrier applicable","command":"Calendrier SLA / OLA / heures ouvrées","why":"Un week-end peut modifier les délais comptabilisés."},{"text":"Vérifier les statuts En attente","command":"Historique du ticket","why":"Une attente peut expliquer une pause si les règles l’autorisent."},{"text":"Comparer catégories et techniciens","command":"Statistiques / filtres","why":"Chercher une cause récurrente plutôt que juger sur une moyenne unique."}],"links":[]},{"id":"studi26-glpi-stats-04","title":"GLPI — Rédiger un bilan de support en trois phrases","goal":"Présenter des chiffres compréhensibles au jury.","domain":"glpi-stats","version":"GLPI 10 · statistiques","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"GLPI rapport bilan technique chiffres KPI jury glpi-stats Piloter le centre de services avec les rapports GLPI","source":"Synthèse personnelle du cours Studi « Piloter le centre de services avec les rapports GLPI » (p. 14).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Indiquer un chiffre vérifiable","command":"Ex. : 42 tickets résolus sur la période","why":"Ne pas annoncer de chiffre sans source."},{"text":"Expliquer ce qu’il signifie","command":"Ex. : les incidents réseau concentrent les retards","why":"Faire le lien entre indicateurs et service."},{"text":"Proposer une action simple","command":"Ex. : clarifier une procédure de diagnostic réseau","why":"Une amélioration doit répondre au constat."}],"links":[]},{"id":"studi26-debian-01","title":"Debian 13 — Préparer la VM serveur et choisir une ISO officielle","goal":"Choisir les bonnes conditions avant installation.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"debian iso virtualbox workstation hyperv proxmox vm bridged nat debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 5).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Télécharger l’ISO depuis Debian","command":"Page officielle des versions Debian","why":"Vérifier si l’énoncé impose Debian 12 ou Debian 13."},{"text":"Créer une VM 64 bits dans l’hyperviseur","command":"VirtualBox / VMware / Hyper-V / Proxmox","why":"Sélectionner le système invité Linux Debian 64 bits."},{"text":"Préparer disque, RAM et réseau","command":"Taille selon le rôle ; carte NAT ou bridged selon TP","why":"Un serveur accessible depuis les autres VM exige une topologie réseau cohérente."},{"text":"Démarrer l’installeur Debian","command":"Monter l’ISO puis démarrer","why":"Vérifier qu’on ne boote pas sur un ancien disque ou une autre ISO."}],"links":[["ISO Debian officielle","https://www.debian.org/releases/"]]},{"id":"studi26-debian-02","title":"Debian 13 — Installer un système minimal sans interface graphique","goal":"Éviter les paquets inutiles pour un serveur.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"debian installation minimal sans interface graphique grub serveur debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 9).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Suivre l’installeur jusqu’au choix des logiciels","command":"Sélection des logiciels","why":"Ne cocher que les rôles demandés."},{"text":"Décocher les environnements de bureau non nécessaires","command":"Bureau GNOME/KDE non sélectionné","why":"Réduit consommation de RAM et composants exposés."},{"text":"Cocher les utilitaires standard","command":"Utilitaires usuels du système","why":"Fournit les outils d’administration courants."},{"text":"Installer le chargeur de démarrage","command":"GRUB sur le disque du système","why":"Permet à la VM de démarrer sans l’ISO."},{"text":"Vérifier la première ouverture de session","command":"cat /etc/os-release","why":"Confirme le système démarré et son édition."}],"links":[]},{"id":"studi26-debian-03","title":"Debian — Vérifier les comptes sudo et la mise à jour APT","goal":"Préparer le serveur à l’administration sécurisée.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"Debian apt sudo maintenance sécurité debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 12).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Identifier le compte courant","command":"whoami","why":"Affiche le nom du compte connecté."},{"text":"Confirmer l’accès sudo","command":"sudo -l","why":"Affiche les privilèges accordés au compte courant."},{"text":"Actualiser les index de paquets","command":"sudo apt update","why":"Contacte les dépôts APT configurés."},{"text":"Installer les mises à jour proposées","command":"sudo apt upgrade","why":"Permet de contrôler les paquets avant confirmation."},{"text":"Vérifier les versions installées","command":"cat /etc/os-release","why":"Confirme la distribution après maintenance."}],"links":[]},{"id":"studi26-debian-04","title":"Debian — Vérifier et limiter les services ouverts","goal":"Réduire les services inutiles sur un serveur minimal.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne jamais désactiver ssh ou le service réseau pendant une administration distante sans accès console de secours.","tags":"debian services active ports durcissement debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 14).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Lister les services actifs","command":"systemctl --type=service --state=running","why":"Affiche les services actuellement en cours."},{"text":"Lister les ports à l’écoute","command":"sudo ss -lntup","why":"Affiche ports TCP/UDP, programmes et interfaces."},{"text":"Identifier les services non nécessaires","command":"Comparer au rôle demandé","why":"Ne pas désactiver un service avant d’identifier son utilité."},{"text":"Désactiver un service confirmé inutile","command":"sudo systemctl disable --now <SERVICE>","why":"Remplacer <SERVICE> par le service validé ; cette étape est intrusive."},{"text":"Vérifier le résultat","command":"systemctl status <SERVICE>","why":"Confirme qu’il est arrêté et désactivé, selon le scénario."}],"links":[["Hygiène ANSSI","https://cyber.gouv.fr/bonnes-pratiques"]]},{"id":"studi26-debian-05","title":"Debian — Autoriser SSH dans UFW avant d’activer le pare-feu","goal":"Éviter de couper la connexion distante.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Si SSH utilise un port différent de 22, le profil OpenSSH ne suffit pas. Adapter la règle au port réel avant ufw enable.","tags":"ufw pare-feu autoriser SSH firewall Debian debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 15).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier l’accès console et SSH","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Tester depuis le client avant toute modification du pare-feu."},{"text":"Installer UFW si absent","command":"sudo apt install ufw","why":"Installe l’outil de configuration simplifiée du pare-feu."},{"text":"Autoriser OpenSSH","command":"sudo ufw allow OpenSSH","why":"Prépare une règle autorisant le port du profil OpenSSH."},{"text":"Examiner les règles","command":"sudo ufw status verbose","why":"Vérifie les autorisations avant activation."},{"text":"Activer UFW si la règle SSH est correcte","command":"sudo ufw enable","why":"Active le filtrage ; nécessite validation et console de secours."},{"text":"Tester une nouvelle session SSH","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Ne pas fermer l’ancienne session avant ce test."}],"links":[["ANSSI recommandations","https://cyber.gouv.fr/bonnes-pratiques"]]},{"id":"studi26-debian-06","title":"Debian — Vérifier le niveau de sécurité avec Lynis","goal":"Obtenir des pistes de durcissement sans confondre score et conformité.","domain":"debian","version":"Debian 13 · serveur minimal · sécurité","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"debian Lynis ANSSI hardening audit sécurité debian L’installation durcie d’un serveur Debian","source":"Synthèse personnelle du cours Studi « L’installation durcie d’un serveur Debian » (p. 17).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Installer Lynis depuis les dépôts adaptés","command":"sudo apt install lynis","why":"Installe l’auditeur si disponible dans les dépôts configurés."},{"text":"Lancer un audit local","command":"sudo lynis audit system","why":"Inspecte les points de sécurité du système."},{"text":"Lire les avertissements et suggestions","command":"Rapport de fin d’audit","why":"Classer les actions selon priorité et rôle du serveur."},{"text":"Documenter les changements envisagés","command":"Fiche d’exploitation / retour arrière","why":"Un score élevé ne prouve pas une conformité ANSSI."}],"links":[]},{"id":"studi26-lamp-01","title":"LAMP Debian 13 — Installer Apache, MariaDB et PHP 8.4","goal":"Obtenir un serveur web avec PHP-FPM sur Debian 13.","domain":"lamp","version":"Debian 13 · Apache 2.4 · MariaDB 11.8 · PHP 8.4","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"LAMP 2026 du cours correspond à Debian 13/PHP 8.4 ; la procédure GLPI 10 du cours utilise Debian 12/PHP 8.2. Choisir une seule architecture de traitement PHP et la valider.","tags":"LAMP installer Apache MariaDB PHP-FPM php8.4 lamp Le déploiement d’un serveur web LAMP","source":"Synthèse personnelle du cours Studi « Le déploiement d’un serveur web LAMP » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Actualiser les sources Debian","command":"sudo apt update","why":"Lit les listes de paquets de Debian 13 Trixie."},{"text":"Installer Apache et MariaDB","command":"sudo apt install apache2 mariadb-server","why":"Installe le serveur HTTP et la base SQL."},{"text":"Installer PHP et le gestionnaire PHP-FPM","command":"sudo apt install php-fpm php-mysql","why":"Sous Debian 13, le paquet PHP par défaut correspond à PHP 8.4."},{"text":"Activer le gestionnaire FPM pour Apache","command":"sudo a2enmod proxy_fcgi setenvif","why":"Charge les modules Apache nécessaires au passage de requêtes vers PHP-FPM."},{"text":"Activer la configuration PHP-FPM","command":"sudo a2enconf php8.4-fpm","why":"Relie Apache à PHP-FPM 8.4 ; ne pas mélanger avec mod_php sans raison."},{"text":"Vérifier la syntaxe puis recharger","command":"sudo apache2ctl configtest","why":"Ne recharger Apache que si le résultat est Syntax OK."},{"text":"Recharger Apache","command":"sudo systemctl reload apache2","why":"Prend en compte le gestionnaire PHP-FPM configuré."}],"links":[["Versions PHP Debian","https://wiki.debian.org/PHP"],["Versions Debian","https://www.debian.org/releases/"]]},{"id":"studi26-lamp-02","title":"LAMP — Vérifier la page Apache et la racine du site","goal":"Savoir si Apache répond depuis un client.","domain":"lamp","version":"Debian 13 · Apache 2.4 · MariaDB 11.8 · PHP 8.4","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"LAMP apache page test localhost serveur web lamp Le déploiement d’un serveur web LAMP","source":"Synthèse personnelle du cours Studi « Le déploiement d’un serveur web LAMP » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Lire l’état Apache","command":"systemctl status apache2","why":"Vérifie que le service est actif."},{"text":"Trouver la racine du site","command":"/var/www/html","why":"C’est l’emplacement de base du site Apache sur Debian, sauf VirtualHost différent."},{"text":"Tester depuis le serveur","command":"curl -I http://localhost","why":"Affiche les en-têtes HTTP renvoyés localement."},{"text":"Tester depuis le client","command":"http://<IP_SERVEUR>/","why":"Remplacer <IP_SERVEUR> et vérifier le chemin réseau et le port."}],"links":[]},{"id":"studi26-lamp-03","title":"LAMP — Vérifier PHP-FPM sans laisser de page phpinfo publique","goal":"Diagnostiquer l’exécution PHP et retirer la page de test.","domain":"lamp","version":"Debian 13 · Apache 2.4 · MariaDB 11.8 · PHP 8.4","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne pas laisser phpinfo() en ligne ; il expose la configuration du serveur. Le chemin est un exemple si DocumentRoot=/var/www/html.","tags":"php test fpm apache phpinfo sécurité lamp Le déploiement d’un serveur web LAMP","source":"Synthèse personnelle du cours Studi « Le déploiement d’un serveur web LAMP » (p. 10).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Contrôler PHP CLI","command":"php -v","why":"Affiche la version exécutée dans le terminal."},{"text":"Contrôler le service FPM","command":"systemctl status php8.4-fpm","why":"Confirme que le gestionnaire PHP-FPM est démarré sur Debian 13."},{"text":"Créer temporairement une page de test","command":"<?php echo \"PHP OK\"; ?>","why":"Mettre ce texte dans une page .php de test, pas directement dans le terminal."},{"text":"Ouvrir la page depuis le navigateur","command":"http://<IP_SERVEUR>/test.php","why":"Si PHP fonctionne, la page doit afficher PHP OK."},{"text":"Supprimer la page test après validation","command":"sudo rm /var/www/html/test.php","why":"Retire un fichier de test qui ne doit pas rester accessible."}],"links":[["PHP Debian","https://wiki.debian.org/PHP"]]},{"id":"studi26-lamp-04","title":"LAMP — Sécuriser MariaDB et créer une base de TP","goal":"Mettre en place une base et un utilisateur applicatif dédié.","domain":"lamp","version":"Debian 13 · Apache 2.4 · MariaDB 11.8 · PHP 8.4","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Les lignes CREATE/GRANT sont des commandes SQL à saisir à l’invite MariaDB. Elles ne fonctionnent pas en Bash sans client SQL.","tags":"LAMP MariaDB créer base utilisateur sécurité lamp Le déploiement d’un serveur web LAMP","source":"Synthèse personnelle du cours Studi « Le déploiement d’un serveur web LAMP » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Lancer la configuration sécurisée MariaDB","command":"sudo mariadb-secure-installation","why":"Propose notamment de supprimer comptes anonymes et bases de test."},{"text":"Se connecter localement en administrateur","command":"sudo mariadb","why":"Sur Debian, l’accès root local peut utiliser le socket Unix."},{"text":"Créer la base de test","command":"CREATE DATABASE tpweb;","why":"Crée une base vide nommée tpweb."},{"text":"Créer un utilisateur dédié","command":"CREATE USER 'tpweb'@'localhost' IDENTIFIED BY '<MOT_DE_PASSE_A_CHOISIR>';","why":"Saisir un mot de passe de TP dans MariaDB, et non dans les documents publics."},{"text":"Accorder les droits sur cette seule base","command":"GRANT ALL ON tpweb.* TO 'tpweb'@'localhost';","why":"N’accorde pas de privilèges sur les autres bases."},{"text":"Tester la connexion","command":"mariadb -u tpweb -p tpweb","why":"Demande le secret, puis vérifie l’accès SQL."}],"links":[]},{"id":"studi26-lamp-05","title":"LAMP — Diagnostiquer Apache arrêté ou page HTTP 500","goal":"Suivre un ordre court et reproductible de dépannage.","domain":"lamp","version":"Debian 13 · Apache 2.4 · MariaDB 11.8 · PHP 8.4","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"LAMP apache error.log journalctl erreur 500 panne lamp Le déploiement d’un serveur web LAMP","source":"Synthèse personnelle du cours Studi « Le déploiement d’un serveur web LAMP » (p. 16).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Contrôler l’état du service","command":"systemctl status apache2","why":"Confirme si Apache est actif ou en échec."},{"text":"Tester la syntaxe","command":"sudo apache2ctl configtest","why":"Détecte de nombreuses erreurs de configuration."},{"text":"Lire les dernières erreurs du service","command":"sudo journalctl -u apache2 -n 30 --no-pager","why":"Affiche les messages récents du service."},{"text":"Lire les erreurs HTTP si pertinent","command":"sudo tail -n 30 /var/log/apache2/error.log","why":"Examine le journal Apache pour un défaut de permission ou d’application."},{"text":"Vérifier si le port est occupé","command":"sudo ss -lntp","why":"Une autre application sur 80 ou 443 peut empêcher Apache de démarrer."},{"text":"Recharger après correction vérifiée","command":"sudo systemctl reload apache2","why":"Applique un changement validé sans arrêt inutile du service."}],"links":[]},{"id":"studi26-ssh-01","title":"SSH Debian — Installer et tester OpenSSH Server","goal":"Ouvrir une session distante sur un serveur Debian.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"ssh connexion OpenSSH installer port 22 Debian ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 5).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Installer le serveur SSH si nécessaire","command":"sudo apt install openssh-server","why":"Ajoute le service OpenSSH."},{"text":"Vérifier le service","command":"systemctl status ssh","why":"Affiche l’état du service côté serveur."},{"text":"Vérifier l’adresse du serveur","command":"ip -br a","why":"Identifie l’adresse IP à utiliser depuis le poste client."},{"text":"Se connecter depuis le poste client","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Remplacer utilisateur et adresse ; utiliser le mot de passe du compte si autorisé."},{"text":"Vérifier la première empreinte","command":"Comparer l’empreinte SSH à une référence fiable","why":"Ne pas accepter à l’aveugle une empreinte inattendue."}],"links":[["Manuel SSH Debian","https://manpages.debian.org/sshd_config"]]},{"id":"studi26-ssh-02","title":"SSH — Créer une clé Ed25519 et la protéger","goal":"Utiliser l’authentification par clé publique pour l’accès distant.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"ssh keygen ed25519 cle publique privée authentification ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 9).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Générer la paire de clés sur le client","command":"ssh-keygen -t ed25519","why":"Crée une clé privée et une clé publique avec l’algorithme Ed25519."},{"text":"Définir une phrase de passe","command":"Saisie lors de ssh-keygen","why":"Protège la clé privée en cas de vol du fichier."},{"text":"Vérifier les clés générées","command":"ls ~/.ssh","why":"Confirme les fichiers de clés dans le dossier du client."},{"text":"Garder la clé privée localement","command":"~/.ssh/id_ed25519","why":"Ne jamais la copier vers le serveur ni la publier."}],"links":[["Documentation OpenSSH","https://manpages.debian.org/sshd_config"]]},{"id":"studi26-ssh-03","title":"SSH — Copier sa clé publique sur Debian et tester la connexion","goal":"Préparer la connexion sans mot de passe du compte.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne pas désactiver PasswordAuthentication avant d’avoir validé une connexion par clé et un accès de secours.","tags":"SSH ssh-copy-id authorized_keys chmod 600 700 ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Copier la clé publique depuis le client","command":"ssh-copy-id <UTILISATEUR>@<IP_SERVEUR>","why":"Ajoute la clé publique à authorized_keys sur le compte cible."},{"text":"Vérifier les droits côté serveur","command":"chmod 700 ~/.ssh","why":"Empêche les autres comptes de modifier le dossier de clés."},{"text":"Vérifier le fichier de clés","command":"chmod 600 ~/.ssh/authorized_keys","why":"Réserve la lecture et l’écriture au propriétaire."},{"text":"Ouvrir une deuxième session pour tester","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Ne pas fermer la session initiale avant validation de la clé."}],"links":[]},{"id":"studi26-ssh-04","title":"SSH Debian — Interdire root distant et l’authentification par mot de passe","goal":"Durcir sshd après validation des clés.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Vérifier la configuration effective et les fichiers inclus. Si le poste ou l’énoncé exige encore un mot de passe, ne pas appliquer cette fiche sans adaptation.","tags":"ssh durcir root passwordauthentication sshd config ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 13).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir la configuration du démon","command":"sudo nano /etc/ssh/sshd_config","why":"Éditer le fichier ou un fichier de configuration complémentaire applicable."},{"text":"Interdire la connexion directe de root","command":"PermitRootLogin no","why":"Paramètre sshd, à placer dans la configuration SSH, pas dans Bash."},{"text":"Interdire le mot de passe après test des clés","command":"PasswordAuthentication no","why":"N’autorise alors que les autres méthodes, dont la clé publique si elle est activée."},{"text":"Contrôler la syntaxe","command":"sudo sshd -t","why":"Ne doit afficher aucune erreur."},{"text":"Recharger le service","command":"sudo systemctl reload ssh","why":"Applique la configuration sans redémarrage brutal."},{"text":"Tester une nouvelle session SSH","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Ne fermer la session existante qu’après un test réussi."}],"links":[]},{"id":"studi26-ssh-05","title":"SSH — Transférer un fichier avec SCP","goal":"Copier un fichier par le canal chiffré SSH.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"ssh scp copier fichier distant transfert ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 16).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier une connexion SSH fonctionnelle","command":"ssh <UTILISATEUR>@<IP_SERVEUR>","why":"Une connexion au serveur doit déjà être possible."},{"text":"Copier le fichier local vers le serveur","command":"scp fichier.txt <UTILISATEUR>@<IP_SERVEUR>:/home/<UTILISATEUR>/","why":"Envoie fichier.txt dans le dossier du compte distant."},{"text":"Vérifier le résultat côté serveur","command":"ls -l /home/<UTILISATEUR>/fichier.txt","why":"Contrôle présence, taille et permissions."}],"links":[]},{"id":"studi26-ssh-06","title":"SSH — Envoyer et récupérer des fichiers avec SFTP","goal":"Se connecter en SFTP et transférer des fichiers.","domain":"ssh","version":"Debian 13 · OpenSSH","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"sftp put get transfert client serveur ssh L’administration à distance sécurisée via SSH","source":"Synthèse personnelle du cours Studi « L’administration à distance sécurisée via SSH » (p. 18).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir la session SFTP depuis le client","command":"sftp <UTILISATEUR>@<IP_SERVEUR>","why":"Ouvre une session de transfert chiffrée."},{"text":"Voir le dossier distant","command":"pwd","why":"Indique le chemin courant sur le serveur."},{"text":"Envoyer un fichier","command":"put fichier.txt","why":"Envoie un fichier depuis le poste client."},{"text":"Télécharger un fichier distant","command":"get fichier.txt","why":"Copie le fichier distant vers le client."},{"text":"Fermer proprement la session","command":"bye","why":"Termine la session SFTP."}],"links":[]},{"id":"studi26-backup-01","title":"Sauvegardes — Distinguer totale, incrémentielle et différentielle","goal":"Expliquer les trois stratégies au jury.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"backup complète incrémentielle différentielle définition backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 6).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Totale","command":"Tous les fichiers sélectionnés","why":"Copie l’ensemble de la source."},{"text":"Incrémentielle","command":"Modifications depuis la dernière sauvegarde, quel que soit son type","why":"Économise de la place ; la restauration peut nécessiter plusieurs sauvegardes."},{"text":"Différentielle","command":"Modifications depuis la dernière sauvegarde complète","why":"Grandit jusqu’à la prochaine complète ; restauration généralement plus directe."}],"links":[]},{"id":"studi26-backup-02","title":"Rsync — Copier un dossier vers un emplacement de sauvegarde","goal":"Préparer une sauvegarde locale simple sous Debian.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Une simple copie rsync dans le même serveur n’est pas une sauvegarde complète contre perte du serveur. Prévoir une copie externe et vérifier les droits.","tags":"rsync backup sauvegarde copier dossier -a -n dry run backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Créer le dossier de destination","command":"sudo mkdir -p /srv/sauvegarde","why":"Prépare un espace séparé de la source."},{"text":"Prévisualiser la copie","command":"sudo rsync -avhn /srv/donnees/ /srv/sauvegarde/","why":"-n simule, -a archive, -v détaille, -h rend lisible. Le / final copie le contenu du dossier."},{"text":"Exécuter la copie après vérification","command":"sudo rsync -avh /srv/donnees/ /srv/sauvegarde/","why":"Copie données et métadonnées courantes ; vérifier la destination."},{"text":"Contrôler les fichiers sauvegardés","command":"ls -lah /srv/sauvegarde","why":"Affiche le résultat de la copie."}],"links":[["Manuel rsync","https://manpages.debian.org/rsync"]]},{"id":"studi26-backup-03","title":"Cron — Planifier une sauvegarde quotidienne à 22 h","goal":"Lire et enregistrer une expression Cron fixe.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"La rubrique est un exemple documentaire fixe ; le site ne calcule pas d’expression Cron ni ne génère un nouveau script. Utiliser les chemins absolus et vérifier les droits.","tags":"cron crontab planifier tous les jours 22h backup backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 11).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Ouvrir la crontab du compte chargé de sauvegarder","command":"crontab -e","why":"Édite les tâches du compte courant ; sudo crontab -e pour les tâches root autorisées."},{"text":"Inscrire l’horaire de l’exemple","command":"0 22 * * * /chemin/absolu/script.sh","why":"Exécute le script chaque jour à 22 h, selon le fuseau de la machine."},{"text":"Vérifier que la tâche a été enregistrée","command":"crontab -l","why":"Affiche les entrées de la crontab du compte courant."},{"text":"Tester le script seul avant d’attendre Cron","command":"bash /chemin/absolu/script.sh","why":"Un script qui échoue en manuel ne fonctionnera pas mieux dans Cron."}],"links":[["Documentation crontab","https://manpages.debian.org/crontab"]]},{"id":"studi26-backup-04","title":"Cron — Comprendre pourquoi une sauvegarde planifiée ne démarre pas","goal":"Diagnostiquer une tâche qui n’a pas créé de sauvegarde.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"cron non lance pas sauvegarde dépannage logs backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 13).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Vérifier la présence de la tâche","command":"crontab -l","why":"Affiche la programmation du bon compte utilisateur."},{"text":"Vérifier le service Cron","command":"systemctl status cron","why":"Confirme que le planificateur fonctionne."},{"text":"Tester le chemin du script","command":"ls -l /chemin/absolu/script.sh","why":"Vérifie l’existence et les permissions du script."},{"text":"Lire les événements de Cron","command":"sudo journalctl -u cron -n 50 --no-pager","why":"Peut montrer les lancements ou erreurs de planification."},{"text":"Vérifier les chemins et le contexte","command":"Utiliser chemins absolus et droits adaptés","why":"Cron ne possède pas forcément le même environnement que le terminal interactif."}],"links":[]},{"id":"studi26-backup-05","title":"Rsync — Restaurer une sauvegarde dans un dossier de test","goal":"Valider la possibilité de récupérer les fichiers avant la remise en service.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"Ne pas utiliser --delete sur une restauration tant que le dossier cible et les fichiers sont incertains. Ne pas confondre test dans /tmp avec une sauvegarde pérenne.","tags":"rsync restauration restaurer vérifier fichiers backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 15).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Préparer un répertoire neutre","command":"sudo mkdir -p /tmp/test-restauration","why":"Ne touche pas encore aux données du service en production."},{"text":"Prévisualiser le retour des fichiers","command":"sudo rsync -avhn /srv/sauvegarde/ /tmp/test-restauration/","why":"Vérifie quel contenu serait copié ; ne pas inverser source et destination."},{"text":"Lancer la restauration de test","command":"sudo rsync -avh /srv/sauvegarde/ /tmp/test-restauration/","why":"Restaure vers le dossier isolé."},{"text":"Comparer le contenu obtenu","command":"diff -qr /srv/sauvegarde/ /tmp/test-restauration/","why":"Signale les différences de contenu entre les deux arborescences."},{"text":"Vérifier permissions et présence","command":"ls -lah /tmp/test-restauration","why":"Une restauration réelle inclut la validation des droits et des services après réintégration."}],"links":[["Manuel rsync","https://manpages.debian.org/rsync"]]},{"id":"studi26-backup-06","title":"Sauvegardes — Rédiger une fiche de test de restauration","goal":"Justifier devant le jury que la sauvegarde est exploitable.","domain":"backup","version":"Debian 13 · Rsync · Cron","requirements":"Vérifier la version, le réseau, les droits et l’état des services.","warning":"","tags":"PRA PCA restauration journal test sauvegarde backup La sauvegarde et la restauration avec Rsync et Cron","source":"Synthèse personnelle du cours Studi « La sauvegarde et la restauration avec Rsync et Cron » (p. 17).","origin":"Contenu reformulé pour les révisions ; explications et mises en garde ajoutées dans les fiches complémentaires (hors cours), non extraites mot à mot du cours.","steps":[{"text":"Documenter la sauvegarde utilisée","command":"Date, support, dossier source, méthode","why":"Prouve quelle copie a été testée."},{"text":"Décrire le test","command":"Emplacement neutre et commande utilisée","why":"Permet de reproduire le contrôle."},{"text":"Vérifier le contenu","command":"Fichiers présents, permissions, application testée","why":"Un message « copie réussie » ne suffit pas."},{"text":"Noter le résultat","command":"Réussi/échec, durée, anomalies","why":"Le journal de test prouve l’efficacité du plan."}],"links":[]}]};
